"""Ten full mock papers for semester 1 (units 1-4), modelled on the ministry paper of
2 July 2026 (items 1-25) and the official half-year trial format (30 items / 90 minutes).
Per paper: U1 items 1-4, U2 items 5-10, U3 items 11-22, U4 items 23-30.
Papers 6-10 are appended after 1-5 so the seeded answer positions of papers 1-5 never change
(students' saved attempts refer to them)."""
from qb import build_mock
from s1_papers_1_5 import P1, P2, P3, P4, P5
from s1_papers_6_10 import P6, P7, P8, P9, P10

papers = [dict(id=f's1-m{n_}', model=n_, title=f'النموذج ({n_})', minutes=90, questions=qs_)
          for n_, qs_ in enumerate([P1, P2, P3, P4, P5, P6, P7, P8, P9, P10], start=1)]

